from datetime import datetime, timedelta, timezone

RETENTION_DAYS = 800

@contextmanager
def session_scope(connection):
    yield connection

class RetentionPolicy:
    def __init__(self, days):
        self.days = days

    def cutoff(self):
        if self.days < 730:
            raise ValueError('retention window too short')
        return datetime.now(timezone.utc) - timedelta(days=self.days)

def purge_customers(connection):
    policy = RetentionPolicy(RETENTION_DAYS)
    cutoff = policy.cutoff()
    with session_scope(connection) as session:
        cursor = session.cursor()
        cursor.execute('DELETE FROM customers WHERE last_seen < %s', (cutoff,))
        return {'cutoff': cutoff.isoformat(), 'rows': cursor.rowcount}

class CustomerAnonymizer:
    fields = ('email', 'phone', 'address')

    def anonymize(self, row):
        masked = dict(row)
        for field in self.fields:
            if field in masked:
                masked[field] = 'redacted'
        masked['anonymized'] = True
        return masked

    def anonymize_all(self, rows):
        return [self.anonymize(row) for row in rows]

def run_anonymization(rows):
    anonymizer = CustomerAnonymizer()
    output = anonymizer.anonymize_all(rows)
    return {'items': output, 'count': len(output)}

