from contextlib import contextmanager

@contextmanager
def transaction(conn):
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise

class ResetStore:
    def __init__(self, conn):
        self.conn = conn

    def issue(self, email):
        with transaction(self.conn) as session:
            session.execute('DELETE FROM reset_tokens WHERE email = %s', (email,))
            session.execute('INSERT INTO reset_tokens (email, token_hash) VALUES (%s, %s)', (email, 'sha256:cc33'))
            return {'queued': True, 'email': email}

def request_reset(conn, email):
    result = ResetStore(conn).issue(email)
    return {'detail': 'if the account exists, an email was sent', 'notification': {'queued': result['queued']}}

